bel": "Study family SF-APPS-010: Play-type PPP change across playoff series game buckets", "score": 0.857, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPS-010 (0.75)", "request matches DS:Play_type_initiation_records_Neo4j_INITIATED_edges_play_type_possessions (0.71); FAM:SF-APPS-010 auto_uses_dataset DS:Play_type_initiation_records_Neo4j_INITIATED_edges_play_type_possessions"], "attributes": {"observed_research_question": "Play-type PPP change across playoff series game buckets", "auto_outcome_status": "inconclusive", "observed_hypothesis": "Play-type PPP (especially DRIVE) declines as a playoff series progresses, so DRIVE is a good early-series call.", "observed_result": "DRIVE 0.889 -> 0.949 (+0.060); CUT +0.114; PNR +0.087; PULL_UP -0.077; POST_UP -0.032.", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "'NO CLEAR SIGNAL - DRIVE PPP is stable or improves across the series'; observational with selection caveats.", "observed_sample_and_power": "1197 records; no CIs", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "Pooled (series, team, PT, bucket) records (1197), EARLY G1-2 / MID G3-4 / LATE G5-7, min 10 poss, min 3 series.", "observed_verdict": "null", "observed_failure_type": "E_unclear"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:selection_or_regression_to_the_mean"}]}, {"id": "FAM:SF18", "label": "Study family SF18: Fragility confirmatory: F1a usage decoupling and F1b split-half stability of residual influence", "score": 0.692, "reached_via": ["FAM:SF17 auto_related_family (record_link_related_to) FAM:SF18", "request matches RQC:RQC-013 (0.72); FAM:SF18 auto_addresses_question RQC:RQC-013"], "attributes": {"observed_research_question": "Fragility confirmatory: F1a usage decoupling and F1b split-half stability of residual influence", "auto_outcome_status": "supported", "observed_hypothesis": "Structural influence i