2b rho=+0.253 p=0.115 NOT"]}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:small_sample"}]}, {"id": "FAM:SF-CHT-009", "label": "Study family SF-CHT-009: Superstar suppression by lineup and forced play type", "score": 0.683, "reached_via": ["request matches RQC:RQC-116 (0.72); FAM:SF-CHT-009 auto_addresses_question RQC:RQC-116", "request matches DS:NBA_play_by_play_possessions_and_reconstructed_lineups (0.80); FAM:SF-CHT-009 auto_uses_dataset DS:NBA_play_by_play_possessions_and_reconstructed_lineups"], "attributes": {"observed_research_question": "Superstar suppression by lineup and forced play type", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Named star initiators have identifiable lineup and forced-play-type suppressors in the possession graph.", "observed_result": "Jokic vs MIN lineup PPP 0.814, -0.385 (n=59); Curry vs HOU 0.851, -0.358 (n=47); Doncic vs LAC 0.733, -0.396 (n=30); Giannis forced PULL_UP 0.848, -0.540 vs preferred DRIVE (largest gap).", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No placebo or matching; later sequence work treated similar star-chain gaps as artifacts.", "observed_sample_and_power": "n>=30 for lineup cells cited", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "Jokic/Curry/Doncic/Giannis; min-15 gate on 8 play types; opposing DEFENSE_LINEUP ~84% coverage; 272-row CSV."}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:PLACEBO_DEPENDENCE"}]}, {"id": "FAM:SF-APPS-013", "label": "Study family SF-APPS-013: Defensive Style Index shift RS vs playoffs", "score": 0.577, "reached_via": ["request matches RQC:RQC-097 (0.71); FAM:SF-APPS-013 auto_addresses_question RQC:RQC-097", "request matches DS:NBA_play_by_play_possessions_and_reconstructed_lineups (0.80); FAM:SF-APPS-013 auto_uses_dataset DS:NBA_play_by_play_possessions_and_reconstructed_lineups"], "attributes": {"observed_research_question": "Defensive Style Index shift RS vs playoffs", "auto_outcome_status": "inconclusive", "observed_hypothesis": "Teams shift toward HELP/SWITCH and away from DROP in the playoffs, making RS DSI priors wrong.", "observed_result": "SWITCH 0.294 -> 0.336 (+0.0426, 62% of teams); DROP 0.399 -> 0.343 (-0.0561); HELP 0.307 -> 0.321 (+0.0135, 'No meaningful shift').", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "HELP shift +0.0135 'No meaningful shift'; per-team shifts range -0.287 to +0.271 with no test.", "observed_sample_and_power": "32 team-seasons; no CIs", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "pbpstats Playoffs vs RS aggregates, same DSI formula, 2022-23 and 2023-24 playoff teams.", "observed_verdict": "null", "observed_failure_type": "E_unclear", "auto_confidence": "medium (0.65)"}, "relationships": [{"rel": "auto_addresses_question", "node": "RQC:RQC-097"}]}, {"id": "FAM:SF-APPS-059", "label": "Study family SF-APPS-059: Sequence-memory horizon test (per-lag vs aggregated window)", "score": 0.51, "reached_via": ["FAM:SF17 auto_related_family (record_link_related_to) FAM:SF-APPS-059", "request matches DS:NBA_play_by_play_possessions_and_reconstructed_lineups (0.80); FAM:SF-APPS-059 auto_uses_dataset DS:NBA_play_by_play_possessions_and_reconstructed_lineups"], "attributes": {"observed_research_question": "Sequence-memory horizon test (per-lag vs aggregated window)", "auto_outcome_status": "supported", "observed_hypothesis": "Increasing prior-possession history changes the opponent's next-possession outcome after controlling for game state.", "observed_result": "Per-lag GBT AUC N=0 0.5621 -> N=1 0.5863 (d+0.0242) -> N=3 0.5907 -> N=8 0.5911. R2 0.0051 -> 0.0133. Aggregated window declines after N=1 (AUC 0.5868 -> 0.5687 at N=8). Effective horizon ~2-3 possessions.", "auto_failure_mechanism": "D_positive (no failure: positive result)", "observed_failure_evidence": "Short-memory horizon is stable OOS; almost all gain is lag-1, plateau by lag 4. Absolute AUC still only ~0.591.", "observed_sample_and_power": "n=1,024,980 possessions; time-split test 2025-26", "observed_verdict": "supported"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}, {"rel": "auto_related_family", "node": "FAM:SF-APPS-070"}, {"rel": "auto_related_family", "node": "FAM:SF17"}]}, {"id": "FAM:SF-PAP-001", "label": "Study family SF-PAP-001: Wiring feasibility gate (8-team pilot)", "score": 0.484, "reached_via": ["FAM:SF17 auto_related_family (record_link_related_to) FAM:SF-PAP-001", "request matches DS:Play_type_initiation_records_Neo4j_INITIATED_edges_play_type_possessions (0.71); FAM:SF-PAP-001 auto_uses_dataset DS:Play_type_initiation_records_Neo4j_INITIATED_edges_play_type_possessions"], "attributes": {"observed_research_question": "Wiring feasibility gate (8-team pilot)", "auto_outcome_status": "supported", "observed_hypothesis": "Offensive play-type co-initiation association matrix clears a fixed-margin null, is team-persistent across split halves, and is not collinear with play-type rates (pilot).", "observed_result": "C1 8/8 p<0.05; C2 S=0.319 within=43.027 between=134.770 perm_p=0.0002 (cosine S=0.154); C3 R2=0.080", "auto_failure_mechanism": "D_positive (no failure: positive result)", "observed_failure_evidence": "all three gate criteria passed", "observed_sample_and_power": "8 team-seasons pilot", "auto_validation_status": "same_pipeline_validation; evidence: PAP-001: '8 frozen pilot team-seasons, odd/even game split, min-overlap associ'", "observed_method": "8 frozen pilot team-seasons, odd/even game split, min-overlap association standardized vs 1000 fixed-margin shuffles; 3 gate criteria.", "observed_verdict": "supported", "observed_failure_type": "D_positive"}, "relationships": []}], "n_results": 10}

